state.allocator_binding:
/* Reviewed first-epoch native binding. Physical containment remains a platform
 * contract; an active statistics callback requires installed unwind guards. */
#include "allocator.h"
#include "admission.h"
#include "bootstrap.h"

extern struct npu_barrier npu_emulation_barrier_state;
extern struct npu_admission npu_emulation_admission_state;
extern struct npu_bootstrap npu_emulation_bootstrap_state;
extern void npu_emulation_mailbox(uint32_t source);
extern void npu_emulation_idle(void) __attribute__((noreturn));

#define BARRIER (&npu_emulation_barrier_state)
#define ADMISSION (&npu_emulation_admission_state)
#define BOOTSTRAP (&npu_emulation_bootstrap_state)

uint32_t npu_emulation_callback_guarded;

typedef uint32_t (*native_hart_id)(void);
typedef int (*native_lock)(uint32_t *lock_id);

#ifdef NPU_EMULATION_COMMAND_RING
__attribute__((section(".command_ring")))
uint32_t npu_emulation_command_ring[0x8010 / sizeof(uint32_t)] = {0xfe};

static const struct npu_allocator_entry placements[] = {
    {0x19, 0, NPU_EMULATION_COMMAND_RING},
};
#endif

static const struct npu_allocator_layout layout = {
    .base = 0x3e800000u,
    .bytes = 0x78000u,
    .tables = {
        (const struct npu_allocator_definition *)(uintptr_t)0x8401b224u,
        (const struct npu_allocator_definition *)(uintptr_t)0x8401cfc8u,
    },
    .lengths = {6, 18},
#ifdef NPU_EMULATION_COMMAND_RING
    .placements = placements,
    .placement_count = sizeof(placements) / sizeof(placements[0]),
#endif
};

static uint32_t load(const uint32_t *word)
{
    return __atomic_load_n(word, __ATOMIC_ACQUIRE);
}

static uint32_t expected_type(uint32_t hart, uint32_t caller)
{
    if (hart == 7)
        return caller == 0x8400148au ? 0x81u : UINT32_MAX;
    if (hart)
        return UINT32_MAX;
    switch (caller) {
    case 0x84005a34u: return 0x89u;
    case 0x84004ecau: return 0x8au;
    case 0x84004eeeu: return 0x12u;
    case 0x84004f2cu: return 0x1du;
    case 0x8400b932u: return 1u;
    case 0x8400a376u: return 0x0bu;
    case 0x8400bab8u: return 0x19u;
    default: return UINT32_MAX;
    }
}

static int acquire(void *context)
{
    struct npu_allocator_state *state = context;

    if (state->lock_id != 18)
        return -1;
    return ((native_lock)(uintptr_t)0x840064b4u)(&state->lock_id);
}

static void release(void *context)
{
    struct npu_allocator_state *state = context;

    ((native_lock)(uintptr_t)0x8400651cu)(&state->lock_id);
}

static int control_available(uint32_t hart, uint32_t status)
{
    uint32_t mie;

    __asm__ volatile ("csrr %0, mie" : "=r"(mie));
    return !hart && (status & 8) && (mie & 0x800) && !ADMISSION->active &&
           *(const volatile uint32_t *)(uintptr_t)0x3e901870u ==
               (uint32_t)(uintptr_t)npu_emulation_mailbox &&
           (*(const volatile uint32_t *)(uintptr_t)0x0c002000u & (1u << 9));
}

__attribute__((noreturn, noinline)) static void fail(uint32_t hart, uint32_t status,
                                                    int service)
{
    __asm__ volatile ("fence iorw, iorw" ::: "memory");
    if (!hart) {
        npu_admission_fail(ADMISSION, BARRIER);
        if (service) {
            __asm__ volatile ("csrw mstatus, %0" :: "r"(status) : "memory");
            npu_emulation_idle();
        }
    } else {
        npu_barrier_fail(BARRIER);
    }
    for (;;) {
        __asm__ volatile (".global npu_emulation_allocator_startup_hold\n"
                          "npu_emulation_allocator_startup_hold:\n nop" ::: "memory");
    }
}

static int startup_lifetime(uint32_t hart)
{
    if (load(&BARRIER->fault) || load(&BARRIER->request) != 1)
        return 0;
    if (ADMISSION->closed != 1 || ADMISSION->active || ADMISSION->fault ||
        BOOTSTRAP->magic != NPU_BOOTSTRAP_MAGIC || BOOTSTRAP->failed || BOOTSTRAP->inflight)
        return 0;
    if (!load(&BARRIER->prepared) && !load(&BARRIER->released) &&
        !load(&BARRIER->armed) && !load(&BARRIER->parked[hart]))
        return 1;
    /* Hart7 calls the bridge initializer after its initial worker gate. Other
     * cold callers remain pre-gate; no later recovery epoch may allocate here.
     * Admission stays closed until this first-boot initialization is complete.
     */
    return hart == 7 && load(&BARRIER->prepared) == 1 &&
           load(&BARRIER->released) == 1 && load(&BARRIER->armed) == 1 &&
           load(&BARRIER->parked[7]) == 1 && load(&BARRIER->ready[7]) == 1 &&
           BOOTSTRAP->step == NPU_BOOTSTRAP_STEPS && BOOTSTRAP->retained_mask == 0x1e &&
           load(&BARRIER->request) == 1;
}

uint32_t npu_emulation_startup_allocate(uint32_t type, uint32_t caller)
{
    struct npu_allocator_state *state = (void *)(uintptr_t)0x3e901bccu;
    const struct npu_allocator_lock lock = {state, acquire, release};
    struct npu_allocator_result result;
    uint32_t status, hart;
    int service;

    __asm__ volatile ("csrrci %0, mstatus, 8" : "=r"(status) :: "memory");
    hart = ((native_hart_id)(uintptr_t)0x84004212u)();
    service = control_available(hart, status);
    if (type >= NPU_ALLOCATOR_TYPES || expected_type(hart, caller) != type ||
        !startup_lifetime(hart) ||
        (!hart && !service))
        fail(hart, status, service);
    result = npu_allocator_allocate(state, &layout, &lock, type, type < 0x81);
    if (result.status != NPU_ALLOCATOR_OK || !startup_lifetime(hart))
        fail(hart, status, service);
    __asm__ volatile ("csrw mstatus, %0" :: "r"(status) : "memory");
    return result.address;
}

uint32_t npu_emulation_callback_lifetime(void)
{
    uint32_t i;

    if (((native_hart_id)(uintptr_t)0x84004212u)() ||
        load(&BARRIER->request) != 1 || load(&BARRIER->fault) ||
        load(&BARRIER->prepared) || load(&BARRIER->released) || load(&BARRIER->armed) ||
        ADMISSION->closed != 1 || ADMISSION->active != 1 || ADMISSION->fault ||
        BOOTSTRAP->magic != NPU_BOOTSTRAP_MAGIC || BOOTSTRAP->failed || BOOTSTRAP->inflight ||
        BOOTSTRAP->step != NPU_BOOTSTRAP_STEPS || BOOTSTRAP->retained_mask != 0x1e)
        return 0;
    for (i = 0; i < NPU_BARRIER_WORKERS; i++)
        if (load(&BARRIER->parked[i]) != 1 || load(&BARRIER->ready[i]))
            return 0;
    return 1;
}

uint32_t npu_emulation_callback_allocate(uint32_t type, uint32_t caller)
{
    struct npu_allocator_state *state = (void *)(uintptr_t)0x3e901bccu;
    const struct npu_allocator_lock lock = {state, acquire, release};
    struct npu_allocator_result result;
    uint32_t status, hart;

    __asm__ volatile ("csrrci %0, mstatus, 8" : "=r"(status) :: "memory");
    hart = ((native_hart_id)(uintptr_t)0x84004212u)();
    if ((status & 8) || !npu_emulation_callback_lifetime() ||
        !((type == 10 && caller == 0x8400a3aeu) || (type == 9 && caller == 0x8400a39au)))
        goto fault;
    result = npu_allocator_allocate(state, &layout, &lock, type, 1);
    if (result.status != NPU_ALLOCATOR_OK || !npu_emulation_callback_lifetime())
        goto fault;
    __asm__ volatile ("csrw mstatus, %0" :: "r"(status) : "memory");
    return result.address;
fault:
    /* NULL may return only to the installed guarded statistics initializer.
     * Otherwise stop here: the original native continuation clears through a0.
     * Already committed metadata remains owned in both failure paths. */
    if (!npu_emulation_callback_guarded)
        fail(hart, 0, 0);
    if (!hart)
        npu_admission_fail(ADMISSION, BARRIER);
    else
        npu_barrier_fail(BARRIER);
    return 0;
}

state.rx_binding:
/* Guarded original RX statistics/initializer composition; no physical proof. */
#include "allocator.h"
#include "bootstrap.h"

extern uint32_t npu_emulation_callback_guarded;
extern uint32_t npu_emulation_callback_lifetime(void);
extern struct npu_barrier npu_emulation_barrier_state;
extern struct npu_admission npu_emulation_admission_state;
extern uint32_t npu_emulation_page_callback(const struct npu_bootstrap_packet *);
extern uint32_t npu_original_rx_dispatch(uint32_t count, uint32_t selector);

static uint32_t word(uint32_t address)
{
    return *(const volatile uint32_t *)(uintptr_t)address;
}

static void fail(void)
{
    npu_admission_fail(&npu_emulation_admission_state, &npu_emulation_barrier_state);
}

uint32_t npu_emulation_rx_stats_valid(uint32_t address, uint32_t type)
{
    const struct npu_allocator_state *state = (const void *)(uintptr_t)0x3e901bccu;
    uint32_t i;

    if (!npu_emulation_callback_lifetime() || (type != 9 && type != 10) ||
        !address || (address & 31) || address < 0x3e800000u ||
        address > 0x3e878000u - 1000 || state->count > NPU_ALLOCATOR_ENTRIES)
        goto fault;
    for (i = 0; i < state->count; i++)
        if (state->entries[i].type == type && !state->entries[i].reserved &&
            state->entries[i].address == address)
            return 1;
fault:
    fail();
    return 0;
}

uint32_t npu_emulation_rx_dispatch_live(uint32_t selector)
{
    uint32_t type = selector ? 9 : 10;

    return npu_emulation_rx_stats_valid(word(selector ? 0x3e901f18u : 0x3e901f04u), type);
}

uint32_t npu_emulation_rx_stats_callback(const struct npu_bootstrap_packet *packet)
{
    struct npu_bootstrap_packet snapshot;
    uint32_t selector = packet->header & 15, status, result = 0, ready;

    if (selector != 0 && selector != 2)
        return npu_emulation_page_callback(packet);
    __asm__ volatile ("csrrci %0, mstatus, 8" : "=r"(status) :: "memory");
    snapshot = *packet;
    ready = selector ? 0x3e904588u : 0x3e902a84u;
    if (snapshot.header != (0x10u | selector) || snapshot.api != 1 || !snapshot.value ||
        snapshot.value > (selector ? 1024u : 1536u) || npu_emulation_callback_guarded ||
        !npu_emulation_callback_lifetime() || word(ready)) {
        fail();
        goto done;
    }
    npu_emulation_callback_guarded = 1;
    result = !npu_original_rx_dispatch(snapshot.value, selector);
    if (!result || !npu_emulation_rx_dispatch_live(selector) || word(ready) != 1) {
        fail();
        *(volatile uint32_t *)(uintptr_t)ready = 0;
        result = 0;
    }
    npu_emulation_callback_guarded = 0;
done:
    __asm__ volatile ("csrw mstatus, %0" :: "r"(status) : "memory");
    return result;
}
